window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-21aad0d99991727b"]={"versions": [{"id": "FIG-21aad0d99991727b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (GST) Metamodell-Spezifikation. Das Diagramm modelliert die Basis-Strukturmuster für referenzierbare und identifizierbare Elemente (<code>Referrable</code>, <code>Identifiable</code>) und definiert deren Adressierungs- und Benennungsmechanismen im statischen Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Basisklasse für referenzierbare AUTOSAR-Elemente mit Attribut <code>+ shortName: Identifier</code>.</li>\n<li><code>SingleLanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName1</code> mit Multiplizität <code>0..1</code> auf <code>SingleLanguageLongName</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName</code> mit Multiplizität <code>0..1</code> auf <code>MultilanguageLongName</code>.</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>, erweitert dieses um Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</li>\n<li><code>SingleLanguageLongName</code> (mit Stereotyp <code>«atpMixedString»</code>, Subtyp von <code>MixedContentForLongName</code>): Repräsentiert einsprachige Langnamen im Fließtext-/Mixed-Content-Format.</li>\n<li><code>MultilanguageLongName</code>: Zielklasse für mehrsprachige Langnamen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Instanzen abgeleiteter Klassen werden bei der Modellerstellung instanziiert; die Eindeutigkeit und Referenzierbarkeit wird über den Bezeichner <code>shortName</code> im jeweiligen Namensraum etabliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Basis für die XML-Serialisierung und Modellvalidierung aller referenzierbaren M1-Modellelemente. <code>shortName</code> ist verpflichtend für die Adressierung über AUTOSAR-Pfadangaben. <code>SingleLanguageReferrable</code> und <code>MultilanguageReferrable</code> erzwingen die Trennung zwischen rein einsprachigen und internationalisierbaren Modellartefakten. Die Attribute <code>category</code> und <code>uuid</code> an <code>Identifiable</code> sind optional (<code>[0..1]</code>).</p>"}, {"id": "FIG-89f34b69f9f73b7f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (GST) Metamodell-Spezifikation. Das Diagramm modelliert die Basis-Strukturmuster für referenzierbare und identifizierbare Elemente (<code>Referrable</code>, <code>Identifiable</code>) und definiert deren Adressierungs- und Benennungsmechanismen im statischen Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Basisklasse für referenzierbare AUTOSAR-Elemente mit Attribut <code>+ shortName: Identifier</code>.</li>\n<li><code>SingleLanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName1</code> mit Multiplizität <code>0..1</code> auf <code>SingleLanguageLongName</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName</code> mit Multiplizität <code>0..1</code> auf <code>MultilanguageLongName</code>.</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>, erweitert dieses um Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</li>\n<li><code>SingleLanguageLongName</code> (mit Stereotyp <code>«atpMixedString»</code>, Subtyp von <code>MixedContentForLongName</code>): Repräsentiert einsprachige Langnamen im Fließtext-/Mixed-Content-Format.</li>\n<li><code>MultilanguageLongName</code>: Zielklasse für mehrsprachige Langnamen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Instanzen abgeleiteter Klassen werden bei der Modellerstellung instanziiert; die Eindeutigkeit und Referenzierbarkeit wird über den Bezeichner <code>shortName</code> im jeweiligen Namensraum etabliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Basis für die XML-Serialisierung und Modellvalidierung aller referenzierbaren M1-Modellelemente. <code>shortName</code> ist verpflichtend für die Adressierung über AUTOSAR-Pfadangaben. <code>SingleLanguageReferrable</code> und <code>MultilanguageReferrable</code> erzwingen die Trennung zwischen rein einsprachigen und internationalisierbaren Modellartefakten. Die Attribute <code>category</code> und <code>uuid</code> an <code>Identifiable</code> sind optional (<code>[0..1]</code>).</p>"}, {"id": "FIG-fb10d40301875232", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (GST) Metamodell-Spezifikation. Das Diagramm modelliert die Basis-Strukturmuster für referenzierbare und identifizierbare Elemente (<code>Referrable</code>, <code>Identifiable</code>) und definiert deren Adressierungs- und Benennungsmechanismen im statischen Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Basisklasse für referenzierbare AUTOSAR-Elemente mit Attribut <code>+ shortName :Identifier</code>. Besitzt eine Komposition <code>+shortNameFragment</code> mit Multiplizität <code>0..*</code> auf <code>ShortNameFragment</code>.</li>\n<li><code>ShortNameFragment</code>: Repräsentiert Namensfragmente zur Konstruktion oder Qualifizierung von Kurznamen mit Attributen <code>+ fragment :Identifier</code> und <code>+ role :String</code>.</li>\n<li><code>SingleLanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName1</code> mit Multiplizität <code>0..1</code> auf <code>SingleLanguageLongName</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName</code> mit Multiplizität <code>0..1</code> auf <code>MultilanguageLongName</code>.</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>, erweitert dieses um Attribute <code>+ category :CategoryString [0..1]</code> und <code>+ uuid :String [0..1]</code>.</li>\n<li><code>SingleLanguageLongName</code> (mit Stereotyp <code>«atpMixedString»</code>, Subtyp von <code>MixedContentForLongName</code>): Zielklasse für einsprachige Langnamen.</li>\n<li><code>MultilanguageLongName</code>: Zielklasse für mehrsprachige Langnamen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Instanzen abgeleiteter Klassen werden bei der Modellerstellung instanziiert; die Eindeutigkeit und Referenzierbarkeit wird über den Bezeichner <code>shortName</code> im jeweiligen Namensraum etabliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Basis für die Modellierung referenzierbarer Entitäten. Über die optionale Aggregation/Komposition <code>shortNameFragment</code> (<code>0..*</code>) können fragmentierte Bezeichnerstrukturen definiert werden, um Namensbildungs- und Rollenkonzepte bei der Bildung des vollständigen Pfadnamens zu unterstützen. <code>shortName</code> bleibt der primäre Identifikator.</p>"}, {"id": "FIG-655d4e90eb729bc4", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (GST) Metamodell-Spezifikation. Das Diagramm modelliert die Basis-Strukturmuster für referenzierbare und identifizierbare Elemente (<code>Referrable</code>, <code>Identifiable</code>) und definiert deren Adressierungs- und Benennungsmechanismen im statischen Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Basisklasse für referenzierbare AUTOSAR-Elemente mit Attribut <code>+ shortName :Identifier</code>. Besitzt eine Komposition <code>+shortNameFragment</code> mit Multiplizität <code>0..*</code> auf <code>ShortNameFragment</code>.</li>\n<li><code>ShortNameFragment</code>: Repräsentiert Namensfragmente zur Konstruktion oder Qualifizierung von Kurznamen mit Attributen <code>+ fragment :Identifier</code> und <code>+ role :String</code>.</li>\n<li><code>SingleLanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName1</code> mit Multiplizität <code>0..1</code> auf <code>SingleLanguageLongName</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName</code> mit Multiplizität <code>0..1</code> auf <code>MultilanguageLongName</code>.</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>, erweitert dieses um Attribute <code>+ category :CategoryString [0..1]</code> und <code>+ uuid :String [0..1]</code>.</li>\n<li><code>SingleLanguageLongName</code> (mit Stereotyp <code>«atpMixedString»</code>, Subtyp von <code>MixedContentForLongName</code>): Zielklasse für einsprachige Langnamen.</li>\n<li><code>MultilanguageLongName</code>: Zielklasse für mehrsprachige Langnamen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Instanzen abgeleiteter Klassen werden bei der Modellerstellung instanziiert; die Eindeutigkeit und Referenzierbarkeit wird über den Bezeichner <code>shortName</code> im jeweiligen Namensraum etabliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Basis für die Modellierung referenzierbarer Entitäten. Über die optionale Aggregation/Komposition <code>shortNameFragment</code> (<code>0..*</code>) können fragmentierte Bezeichnerstrukturen definiert werden, um Namensbildungs- und Rollenkonzepte bei der Bildung des vollständigen Pfadnamens zu unterstützen. <code>shortName</code> bleibt der primäre Identifikator.</p>"}, {"id": "FIG-0cee5879d35a91b1", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (GST) Metamodell-Spezifikation. Das Diagramm modelliert die Basis-Strukturmuster für referenzierbare und identifizierbare Elemente (<code>Referrable</code>, <code>Identifiable</code>) und definiert deren Adressierungs- und Benennungsmechanismen im statischen Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Basisklasse für referenzierbare AUTOSAR-Elemente mit Attribut <code>«atpIdentityContributor» + shortName: Identifier</code>. Besitzt eine Komposition <code>+shortNameFragment</code> mit Multiplizität <code>0..*</code> auf <code>ShortNameFragment</code>.</li>\n<li><code>ShortNameFragment</code>: Repräsentiert Namensfragmente mit Attributen <code>+ fragment: Identifier</code> und <code>+ role: String</code>.</li>\n<li><code>SingleLanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName1</code> mit Multiplizität <code>0..1</code> auf <code>SingleLanguageLongName</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName</code> mit Multiplizität <code>0..1</code> auf <code>MultilanguageLongName</code>.</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code> mit Attributen <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</li>\n<li><code>SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Spezialisierung von <code>MixedContentForLongName</code>): Einsprachiger Langname.</li>\n<li><code>MultilanguageLongName</code>: Zielklasse für mehrsprachige Langnamen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Instanzen abgeleiteter Klassen werden bei der Modellerstellung instanziiert; die Eindeutigkeit und Referenzierbarkeit wird über den Bezeichner <code>shortName</code> im jeweiligen Namensraum etabliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Stereotyp <code>«atpIdentityContributor»</code> an <code>shortName</code> kennzeichnet normativ, dass das Attribut zur Identitäts- und Pfadbildung der Entität beiträgt. Für Modellierungs- und Werkzeugketten bedeutet dies, dass <code>shortName</code> maßgeblich für die kanonische Referenzierung und Identitätsfeststellung im Modellbaum ist.</p>"}, {"id": "FIG-5a80bf2eb2892900", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (GST) Metamodell-Spezifikation. Das Diagramm modelliert die Basis-Strukturmuster für referenzierbare und identifizierbare Elemente (<code>Referrable</code>, <code>Identifiable</code>) und definiert deren Adressierungs- und Benennungsmechanismen im statischen Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Basisklasse für referenzierbare AUTOSAR-Elemente mit Attribut <code>«atpIdentityContributor» + shortName: Identifier</code>. Besitzt eine Komposition <code>+shortNameFragment</code> mit Multiplizität <code>0..*</code> auf <code>ShortNameFragment</code>.</li>\n<li><code>ShortNameFragment</code>: Repräsentiert Namensfragmente mit Attributen <code>+ fragment: Identifier</code> und <code>+ role: String</code>.</li>\n<li><code>SingleLanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName1</code> mit Multiplizität <code>0..1</code> auf <code>SingleLanguageLongName</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>, besitzt eine Komposition <code>+longName</code> mit Multiplizität <code>0..1</code> auf <code>MultilanguageLongName</code>.</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code> mit Attributen <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</li>\n<li><code>SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Spezialisierung von <code>MixedContentForLongName</code>): Einsprachiger Langname.</li>\n<li><code>MultilanguageLongName</code>: Zielklasse für mehrsprachige Langnamen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Instanzen abgeleiteter Klassen werden bei der Modellerstellung instanziiert; die Eindeutigkeit und Referenzierbarkeit wird über den Bezeichner <code>shortName</code> im jeweiligen Namensraum etabliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Stereotyp <code>«atpIdentityContributor»</code> an <code>shortName</code> kennzeichnet normativ, dass das Attribut zur Identitäts- und Pfadbildung der Entität beiträgt. Für Modellierungs- und Werkzeugketten bedeutet dies, dass <code>shortName</code> maßgeblich für die kanonische Referenzierung und Identitätsfeststellung im Modellbaum ist.</p>"}], "trans": [{"from": "FIG-21aad0d99991727b", "to": "FIG-89f34b69f9f73b7f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Leerraum- und Formatierungsanpassung bei Typdeklarationen (z. B. <code>+ shortName :Identifier</code> statt <code>+ shortName: Identifier</code>, <code>+ category :CategoryString [0..1]</code>, <code>+ uuid :String [0..1]</code>).</li>\n</ul>"}, {"from": "FIG-89f34b69f9f73b7f", "to": "FIG-fb10d40301875232", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>ShortNameFragment</code> mit Attributen <code>+ fragment :Identifier</code> und <code>+ role :String</code>.</li>\n<li>Kompositionsbeziehung von <code>Referrable</code> zu <code>ShortNameFragment</code> über die Rolle <code>+shortNameFragment</code> mit Kardinalität <code>0..*</code>.</li>\n</ul>"}, {"from": "FIG-fb10d40301875232", "to": "FIG-655d4e90eb729bc4", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Leerraumanpassung bei Attribut-Typdefinitionen (<code>+ shortName: Identifier</code> statt <code>+ shortName :Identifier</code>, <code>+ category: CategoryString [0..1]</code> statt <code>+ category :CategoryString [0..1]</code>, <code>+ uuid: String [0..1]</code> statt <code>+ uuid :String [0..1]</code>, <code>+ fragment: Identifier</code> statt <code>+ fragment :Identifier</code>, <code>+ role: String</code> statt <code>+ role :String</code>).</li>\n</ul>"}, {"from": "FIG-655d4e90eb729bc4", "to": "FIG-0cee5879d35a91b1", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>shortName</code> in <code>Referrable</code> mit dem Stereotyp <code>«atpIdentityContributor»</code> versehen.</li>\n</ul>"}, {"from": "FIG-0cee5879d35a91b1", "to": "FIG-5a80bf2eb2892900", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
